use std::collections::VecDeque;
use std::path::PathBuf;
use std::sync::{Mutex, MutexGuard};

use serde::Serialize;
use tokio::sync::Semaphore;
use uuid::Uuid;

use crate::domain::project::{Project, ProjectSettings};

/// Thumbnails are generated by at most this many FFmpeg processes at once.
const MAX_THUMBNAIL_JOBS: usize = 2;

/// Undo steps kept in memory. Projects hold metadata only, so snapshots are small.
const MAX_HISTORY: usize = 200;

pub const UNTITLED: &str = "Untitled";

/// A project snapshot plus the id of that state, used for dirty tracking.
type HistoryEntry = (Project, u64);

/// The open project. The backend owns the canonical copy; the frontend only
/// ever receives snapshots of it.
pub struct Session {
    pub project: Project,
    pub path: Option<PathBuf>,
    /// Identifies the current project state. Every commit gets a fresh id and
    /// undo/redo restore the id of the state they return to, so undoing back
    /// to the saved state clears the dirty flag.
    pub state_id: u64,
    pub saved_state_id: u64,
    next_state_id: u64,
    undo: VecDeque<HistoryEntry>,
    redo: Vec<HistoryEntry>,
}

impl Session {
    pub fn new(project: Project, path: Option<PathBuf>) -> Self {
        Self {
            project,
            path,
            state_id: 0,
            saved_state_id: 0,
            next_state_id: 1,
            undo: VecDeque::new(),
            redo: Vec::new(),
        }
    }

    pub fn untitled() -> Self {
        Self::new(Project::new(UNTITLED, ProjectSettings::default()), None)
    }

    /// Replaces the project with an already-validated new state, recording
    /// the previous state for undo.
    pub fn commit(&mut self, project: Project) {
        let previous = std::mem::replace(&mut self.project, project);
        self.undo.push_back((previous, self.state_id));
        if self.undo.len() > MAX_HISTORY {
            self.undo.pop_front();
        }
        self.redo.clear();
        self.state_id = self.next_state_id;
        self.next_state_id += 1;
    }

    pub fn undo(&mut self) -> bool {
        let Some((project, id)) = self.undo.pop_back() else {
            return false;
        };
        let current = std::mem::replace(&mut self.project, project);
        self.redo.push((current, self.state_id));
        self.state_id = id;
        true
    }

    pub fn redo(&mut self) -> bool {
        let Some((project, id)) = self.redo.pop() else {
            return false;
        };
        let current = std::mem::replace(&mut self.project, project);
        self.undo.push_back((current, self.state_id));
        self.state_id = id;
        true
    }

    pub fn snapshot(&self) -> ProjectState {
        ProjectState {
            project: self.project.clone(),
            path: self.path.as_ref().map(|p| p.display().to_string()),
            dirty: self.state_id != self.saved_state_id,
            can_undo: !self.undo.is_empty(),
            can_redo: !self.redo.is_empty(),
            missing_asset_ids: self
                .project
                .assets
                .iter()
                .filter(|a| !a.path.is_file())
                .map(|a| a.id)
                .collect(),
        }
    }
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ProjectState {
    pub project: Project,
    pub path: Option<String>,
    pub dirty: bool,
    pub can_undo: bool,
    pub can_redo: bool,
    pub missing_asset_ids: Vec<Uuid>,
}

pub struct AppState {
    session: Mutex<Session>,
    pub thumbnail_jobs: Semaphore,
}

impl AppState {
    pub fn new() -> Self {
        Self {
            session: Mutex::new(Session::untitled()),
            thumbnail_jobs: Semaphore::new(MAX_THUMBNAIL_JOBS),
        }
    }

    /// Locks the session. Never hold the guard across an `.await` or a
    /// blocking media operation.
    pub fn session(&self) -> MutexGuard<'_, Session> {
        self.session
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn renamed(session: &Session, name: &str) -> Project {
        let mut project = session.project.clone();
        project.name = name.into();
        project
    }

    #[test]
    fn commit_marks_dirty_and_enables_undo() {
        let mut session = Session::untitled();
        assert!(!session.snapshot().dirty);
        session.commit(renamed(&session, "A"));
        let snap = session.snapshot();
        assert!(snap.dirty && snap.can_undo && !snap.can_redo);
    }

    #[test]
    fn undo_and_redo_restore_states() {
        let mut session = Session::untitled();
        session.commit(renamed(&session, "A"));
        session.commit(renamed(&session, "B"));

        assert!(session.undo());
        assert_eq!(session.project.name, "A");
        assert!(session.redo());
        assert_eq!(session.project.name, "B");
        assert!(!session.redo());
    }

    #[test]
    fn undo_back_to_saved_state_is_clean() {
        let mut session = Session::untitled();
        session.commit(renamed(&session, "A"));
        session.saved_state_id = session.state_id;
        session.commit(renamed(&session, "B"));
        assert!(session.snapshot().dirty);
        session.undo();
        assert!(!session.snapshot().dirty);
    }

    #[test]
    fn new_commit_clears_redo() {
        let mut session = Session::untitled();
        session.commit(renamed(&session, "A"));
        session.undo();
        session.commit(renamed(&session, "C"));
        assert!(!session.snapshot().can_redo);
    }

    #[test]
    fn history_is_bounded() {
        let mut session = Session::untitled();
        for i in 0..MAX_HISTORY + 10 {
            session.commit(renamed(&session, &i.to_string()));
        }
        let mut steps = 0;
        while session.undo() {
            steps += 1;
        }
        assert_eq!(steps, MAX_HISTORY);
    }
}
